<template><main style="max-width:700px;margin:100px auto;padding:16px"><h1>Settings — Database</h1><div class="card" style="padding:16px"><h3>Neon DB</h3><input v-model="neon" placeholder="DATABASE_URL postgres://...neon.tech" style="width:100%;padding:12px" /><h3>Cloudflare R2</h3><input v-model="r2" placeholder="R2_BUCKET" style="width:100%;padding:12px;margin:6px 0" /><input v-model="acc" placeholder="CLOUDFLARE_ACCOUNT_ID" style="width:100%;padding:12px" /><p>Status: <b>{{status}}</b></p><button class="btn-primary" @click="test">Test Connection</button><button @click="save">Save Configuration</button><p style="color:#a1a1aa">If not configured, status = Setup Required. No fake connection.</p></div></main></template>
<script setup lang="ts">import {ref} from 'vue'; const neon=ref(''); const r2=ref(''); const acc=ref(''); const status=ref('Setup Required'); function test(){ status.value = neon.value.startsWith('postgres://') && neon.value.includes('neon.tech') && r2.value ? 'Connected (format valid)' : 'Error — check DATABASE_URL / R2 fields' } function save(){ localStorage.setItem('mv_neon',neon.value); localStorage.setItem('mv_r2',r2.value); status.value='Saved' }</script>
